mapper.select:
SELECT p.grid_id AS code,
       (p.age_3544 + p.age_4554)::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code,
       p.gender_male::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code,
       p.has_car::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code,
       p.qualification_undergraduate_graduate::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code, (hf.num / 14400.0) / #{totalArea} AS result
FROM tb_grid_pop_attr1 p
JOIN tb_grid_hour_flow hf ON p.grid_id = hf.grid_id
WHERE p.grid_id IN #{item}
  AND p.date = #{date}

SELECT p.grid_id AS code, (pn.num / 14400.0) / #{avgPerGrid} AS result
FROM tb_grid_pop_attr1 p
JOIN tb_grid_permanent_num pn ON p.grid_id = pn.grid_id AND pn.population_type = 'HOME'
WHERE p.grid_id IN #{item}
  AND p.date = #{date}

SELECT p.grid_id AS code, (pn.num / 14400.0) / #{avgPerGrid} AS result
FROM tb_grid_pop_attr1 p
JOIN tb_grid_permanent_num pn ON p.grid_id = pn.grid_id AND pn.population_type = 'WORK'
WHERE p.grid_id IN #{item}
  AND p.date = #{date}

SELECT p.grid_id AS code, (work_flow.num / NULLIF(holiday_flow.num, 0)) AS result
FROM tb_grid_pop_attr1 p
JOIN tb_grid_hour_flow work_flow ON p.grid_id = work_flow.grid_id AND work_flow.type = 'WROK_HOUR_FLOW'
JOIN tb_grid_hour_flow holiday_flow ON p.grid_id = holiday_flow.grid_id AND holiday_flow.type = 'HOLIDAY_HOUR_FLOW'
WHERE p.grid_id IN #{item}
  AND p.date = #{date}

SELECT p.grid_id AS code, p.asset_grade_high::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code, p.income_20000::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code, p.income_9999::numeric / NULLIF((p.gender_female + p.gender_male), 0) AS result
FROM tb_grid_pop_attr1 p
WHERE p.grid_id IN #{item}
  AND p.date = #{date} AND p.population_type = #{populationType}

SELECT p.grid_id AS code, COALESCE(SUM(loc.num), 0) AS result
FROM tb_grid_pop_attr1 p
LEFT JOIN tb_grid_geo_loc loc ON p.grid_id = loc.grid_id
WHERE p.grid_id IN #{item}
  AND p.date = #{date}

      AND loc.level2_classification IN
      #{lv2}


      AND loc.level1_classification = #{level1}

GROUP BY p.grid_id
